"src/access.js": function (module, exports, require, __dirname) {

// ONE place that decides whether a user may use the EGS platform. Every protected route calls hasEGSAccess().
const { iso, lagosToday, addMonthsUTC } = require('./util');

const RANK = { free_until_graduation: 4, free_forever: 3, free_until_date: 2 };
const GRANT_TYPE = { until_graduation: 'free_until_graduation', until_date: 'free_until_date', forever: 'free_forever' };

function evalFree(type, accessUntil, user, today) {
  if (type === 'free_until_graduation') {                      // follows the user's graduation_date (owner-controlled)
    const g = user.graduation_date;
    return g && today <= g ? { type, until: g } : null;        // INCLUSIVE: valid through the graduation date (Lagos)
  }
  if (type === 'free_until_date') return accessUntil && today <= accessUntil ? { type, until: accessUntil } : null;
  if (type === 'free_forever') return { type, until: null };
  return null;
}

function bestFreeAccess(db, user, now) {
  const today = lagosToday(now);
  const found = [];
  const reds = db.prepare(`SELECT r.access_until AS until_, p.type FROM promo_redemptions r
                           JOIN promo_codes p ON p.id = r.promo_id WHERE r.user_id = ? AND r.revoked_at IS NULL`).all(user.id);
  for (const r of reds) { const e = evalFree(r.type, r.until_, user, today); if (e) found.push(e); }
  const grants = db.prepare('SELECT kind, access_until FROM access_grants WHERE user_id = ? AND revoked_at IS NULL').all(user.id);
  for (const g of grants) { const e = evalFree(GRANT_TYPE[g.kind], g.access_until, user, today); if (e) found.push(e); }
  found.sort((a, b) => RANK[b.type] - RANK[a.type] || String(b.until || '9999').localeCompare(String(a.until || '9999')));
  return found[0] || null;
}

function paidState(db, userId, now) {
  const s = db.prepare('SELECT status, current_period_end FROM subscriptions WHERE user_id = ?').get(userId);
  if (!s) return null;
  const active = s.status !== 'expired' && s.current_period_end > iso(now);
  return { status: s.status, periodEnd: s.current_period_end, active };
}

// Returns { allowed, level, until, reason }. level: owner | free_until_graduation | promo | paid | pending | none
function hasEGSAccess(db, user, session, now = new Date()) {
  const no = (reason, level = 'none', until = null) => ({ allowed: false, level, until, reason });
  if (!user || user.disabled_at) return no('account_disabled');
  if (user.role === 'owner') {
    return session && session.elevated ? { allowed: true, level: 'owner', until: null, reason: 'owner' } : no('owner_login_required');
  }
  const free = bestFreeAccess(db, user, now);
  if (free) return { allowed: true, level: free.type === 'free_until_graduation' ? 'free_until_graduation' : 'promo', until: free.until, reason: free.type };
  const paid = paidState(db, user.id, now);
  if (paid && paid.active) return { allowed: true, level: 'paid', until: lagosToday(new Date(paid.periodEnd)), reason: 'subscription' };
  const pending = db.prepare("SELECT 1 FROM payments WHERE user_id = ? AND status = 'pending' AND created_at > ?")
    .get(user.id, iso(new Date(now.getTime() - 864e5)));
  return pending ? no('payment_pending', 'pending') : no('no_access');
}

// ---- subscription service: the only code that writes subscriptions ----
function extendSubscription(db, userId, amount, currency, now, providerId) {
  const cur = db.prepare('SELECT * FROM subscriptions WHERE user_id = ?').get(userId);
  const base = cur && cur.status !== 'expired' && cur.current_period_end > iso(now) ? new Date(cur.current_period_end) : now;
  let end = iso(addMonthsUTC(base, 1));
  if (cur) {
    if (cur.current_period_end > end) end = cur.current_period_end;          // never shorten an already-paid period
    db.prepare(`UPDATE subscriptions SET status='active', amount=?, currency=?, current_period_end=?,
                provider_subscription_id=COALESCE(?, provider_subscription_id) WHERE user_id=?`)
      .run(amount, currency, end, providerId || null, userId);
  } else {
    db.prepare(`INSERT INTO subscriptions (user_id, status, plan, amount, currency, interval, provider, provider_subscription_id, current_period_end)
                VALUES (?, 'active', 'egs_monthly', ?, ?, 'month', 'flutterwave', ?, ?)`).run(userId, amount, currency, providerId || null, end);
  }
  return end;
}
function cancelSubscriptionNow(db, userId, now) {
  return db.prepare("UPDATE subscriptions SET status='cancelled', current_period_end=? WHERE user_id=?").run(iso(now), userId).changes;
}

module.exports = { hasEGSAccess, extendSubscription, cancelSubscriptionNow, bestFreeAccess, paidState };

},
